              <span className="mr-[10px] shrink-0 text-[20px] font-bold leading-none text-[#2B001F] max-[767px]:absolute max-[767px]:left-0 max-[767px]:top-[5px]"><span className="group-open:hidden">+</span><span className="hidden group-open:inline">−</span></span>
